'use strict';
const KEY='df4-unit1-sound-check-v1';
let state={answers:{},ratings:{},section:0,checked:false,remaining:1080};
let storageWorks=true;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&typeof saved==='object'){state.answers=saved.answers&&typeof saved.answers==='object'?saved.answers:{};state.ratings=saved.ratings&&typeof saved.ratings==='object'?saved.ratings:{};state.section=Number.isInteger(saved.section)&&saved.section>=0&&saved.section<SECTIONS.length?saved.section:0;state.checked=saved.checked===true&&QUESTIONS.every(q=>answered(q,state.answers));state.remaining=Number.isFinite(saved.remaining)?Math.max(0,Math.min(1080,saved.remaining)):1080;}}catch{storageWorks=false;}
let ticking=null;
const $=id=>document.getElementById(id);
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));$('saveState').textContent='Answers save automatically in this browser.';storageWorks=true;}catch{storageWorks=false;$('saveState').textContent='This browser cannot save automatically. Use “Save answer copy” before leaving.';}}
function completed(){return QUESTIONS.filter(q=>answered(q,state.answers)).length;}
function renderNav(){$('sectionNav').innerHTML=SECTIONS.map((s,i)=>{const qs=QUESTIONS.filter(q=>q.section===s.id);return `<button data-section="${i}" class="${i===state.section?'active':''}" ${i===state.section?'aria-current="step"':''}><span class="disc" style="background:${s.color}">${String(i+1).padStart(2,'0')}</span><span class="nav-label">${s.title}<br><small>${qs.filter(q=>answered(q,state.answers)).length}/${qs.length} answered · ${s.time}</small></span></button>`;}).join('');}
function updateProgress(){const count=completed();$('count').textContent=`${count} / 20 questions answered`;$('progress').value=count;$('modeLabel').textContent=state.checked?'Answer guide unlocked':'Answer first · check later';$('finishNote').textContent=state.checked?'Compare all six short responses, then use your topic profile.':count===20?'Ready. Check your choices and compare your short responses.':'Answer all 20 questions to unlock the answer guide.';$('check').textContent=state.checked?'View my topic profile':'Check my review';renderNav();}
function feedback(q){if(!state.checked)return '';if(q.type==='mc'){const correct=state.answers[q.id]===q.answer;return `<div class="feedback"><span class="badge ${correct?'':'again'}">${correct?'Correct':'Review this idea'}</span><p><strong>Answer ${String.fromCharCode(65+q.answer)}:</strong> ${escapeHtml(q.options[q.answer])}</p><p>${escapeHtml(q.explanation)}</p></div>`;}return `<div class="feedback"><strong>Compare your response</strong><p class="model"><strong>One possible answer:</strong> ${escapeHtml(q.model)}</p><ul class="checks">${q.checks.map(c=>`<li>${escapeHtml(c)}</li>`).join('')}</ul><p>${escapeHtml(q.explanation)}</p><div class="self-rating" role="group" aria-label="Self-check question ${q.id}">${[{n:2,label:'Meets both checks'},{n:1,label:'Meets one check'},{n:0,label:'Needs revision'}].map(r=>`<button data-rate="${q.id}" data-value="${r.n}" class="${state.ratings[q.id]===r.n?'chosen':''}" aria-pressed="${state.ratings[q.id]===r.n}">${r.label}</button>`).join('')}</div><p class="hint">This is your own comparison, not an automatic grade. Different wording is welcome.</p></div>`;}
function renderQuestion(q){const value=state.answers[q.id];return `<article class="question" id="q${q.id}"><span class="question-number">QUESTION ${String(q.id).padStart(2,'0')} · ${q.type==='mc'?'CHOOSE ONE':'ONE SENTENCE'}</span><h3 id="prompt${q.id}">${escapeHtml(q.prompt)}</h3>${q.type==='mc'?`<fieldset class="options" aria-labelledby="prompt${q.id}"><legend>Question ${q.id}</legend>${q.options.map((o,i)=>`<label class="choice ${state.checked&&i===q.answer?'correct':''} ${state.checked&&value===i&&i!==q.answer?'incorrect':''}"><input type="radio" name="q${q.id}" value="${i}" data-question="${q.id}" ${value===i?'checked':''} ${state.checked?'disabled':''}><span><strong>${String.fromCharCode(65+i)}.</strong> ${escapeHtml(o)}</span></label>`).join('')}</fieldset>`:`<textarea class="answer-input" id="answer${q.id}" data-question="${q.id}" aria-labelledby="prompt${q.id}" aria-describedby="hint${q.id}" rows="2" maxlength="320" placeholder="Write one brief sentence…" ${state.checked?'disabled':''}>${escapeHtml(value||'')}</textarea><p class="hint" id="hint${q.id}">One sentence is enough. Aim for about 10–25 words.</p>`}${feedback(q)}</article>`;}
function renderSection(){const s=SECTIONS[state.section];$('sectionContent').innerHTML=`<div class="section-heading" style="background:${s.color}"><p class="eyebrow">SECTION ${String(state.section+1).padStart(2,'0')} / 06 · ABOUT ${s.time.toUpperCase()}</p><h2>${s.title}</h2><p>${s.subtitle}</p></div>`+QUESTIONS.filter(q=>q.section===s.id).map(renderQuestion).join('');$('prev').disabled=state.section===0;$('next').disabled=state.section===SECTIONS.length-1;updateProgress();}
function move(i,scroll=true){state.section=i;persist();renderSection();$('status').textContent='';if(scroll){$('sectionContent').scrollIntoView({behavior:'smooth',block:'start'});const first=$('sectionContent').querySelector('h2');first.tabIndex=-1;first.focus({preventScroll:true});}}
function summaryText(s,r){const names=QUESTIONS.filter(q=>q.section===s.id&&q.type==='mc'&&state.answers[q.id]!==q.answer).map(q=>'Q'+q.id);return names.length?`Revisit ${names.join(', ')} and read the explanations.`:'All multiple-choice answers in this topic are correct.';}
function renderProfile(){if(!state.checked){$('profile').hidden=true;return;}$('profile').hidden=false;const mc=QUESTIONS.filter(q=>q.type==='mc');const correct=mc.filter(q=>state.answers[q.id]===q.answer).length;const reviewed=QUESTIONS.filter(q=>q.type==='short'&&[0,1,2].includes(state.ratings[q.id])).length;$('profile').innerHTML=`<p class="eyebrow">YOUR REVIEW EVIDENCE</p><h2>See where you stand.</h2><p class="results-intro"><strong>${correct}/14 multiple-choice answers correct.</strong> You have compared ${reviewed}/6 short responses with the guide. Use the topic cards and question numbers when you reflect on your learning. A topic card is a small sample, not a final judgement of your ability.</p><div class="profile-grid">${SECTIONS.map((s,i)=>{const r=resultsFor(s.id,state.answers,state.ratings);return `<div class="profile-card" style="border-top:4px solid ${s.color}"><h3>${s.title}</h3><div class="score">${r.correct}/${r.total} <small>choices correct</small></div><p>${summaryText(s,r)}</p><p><strong>Short response:</strong> ${r.reviewed===0?'Not compared yet':r.shortPoints===2?'Both checks met (self-rated)':r.shortPoints===1?'One check met (self-rated)':'Needs revision (self-rated)'}</p><button data-section="${i}">Review this topic →</button></div>`;}).join('')}</div><div class="key"><strong>Use your evidence:</strong> “Choices correct” is checked automatically. “Short response” is your comparison with the two checks. Focus your next practice on incorrect choices or a short response that needs revision.</div><div class="profile-actions"><button class="primary" id="printResults">Print / save my review as PDF</button><button class="quiet" id="downloadResults">Save answer copy</button></div>`;}
function timerDisplay(){$('clock').textContent=String(Math.floor(state.remaining/60)).padStart(2,'0')+':'+String(state.remaining%60).padStart(2,'0');}
function pauseTimer(){clearInterval(ticking);ticking=null;$('timerBtn').textContent=state.remaining===0?'Finished':'Start';persist();}
$('timerBtn').addEventListener('click',()=>{if(ticking){pauseTimer();return;}if(state.remaining===0)return;$('timerBtn').textContent='Pause';ticking=setInterval(()=>{state.remaining=Math.max(0,state.remaining-1);timerDisplay();persist();if(state.remaining===0){pauseTimer();$('timerNote').textContent='18 minutes have passed. Finish at your own pace.';}},1000);});
$('timerReset').addEventListener('click',()=>{pauseTimer();state.remaining=1080;timerDisplay();$('timerBtn').textContent='Start';$('timerNote').textContent='A guide, not a deadline. Nothing locks when time runs out.';persist();});
document.addEventListener('click',event=>{const nav=event.target.closest('[data-section]');if(nav){move(Number(nav.dataset.section));return;}const rate=event.target.closest('[data-rate]');if(rate&&state.checked){state.ratings[rate.dataset.rate]=Number(rate.dataset.value);persist();const group=rate.parentElement;group.querySelectorAll('button').forEach(b=>{const chosen=b===rate;b.classList.toggle('chosen',chosen);b.setAttribute('aria-pressed',String(chosen));});renderProfile();}});
$('sectionContent').addEventListener('change',e=>{if(state.checked||e.target.type!=='radio')return;state.answers[e.target.dataset.question]=Number(e.target.value);persist();updateProgress();});
$('sectionContent').addEventListener('input',e=>{if(state.checked||e.target.tagName!=='TEXTAREA')return;state.answers[e.target.dataset.question]=e.target.value;persist();updateProgress();});
$('prev').addEventListener('click',()=>move(state.section-1));$('next').addEventListener('click',()=>move(state.section+1));
$('check').addEventListener('click',()=>{if(state.checked){$('profile').scrollIntoView({behavior:'smooth'});$('profile').focus({preventScroll:true});return;}const missing=QUESTIONS.filter(q=>!answered(q,state.answers));if(missing.length){move(SECTIONS.findIndex(s=>s.id===missing[0].section));$('status').textContent=`${missing.length} question${missing.length===1?'':'s'} still need an answer. Start with question ${missing[0].id}.`;$('q'+missing[0].id).querySelector('input,textarea').focus();return;}state.checked=true;pauseTimer();persist();renderSection();renderProfile();$('status').textContent='Answer guide unlocked. Compare each short response with its two checks.';$('sectionContent').scrollIntoView({behavior:'smooth'});});
function saveAnswerCopy(){let text='DISCOVER FUTURES 4 · UNIT 1 · SOUND CHECK\n'+new Date().toLocaleString()+'\n'+(state.checked?'Completed review with answer guide':'Review in progress')+'\n\n';SECTIONS.forEach(s=>{text+=s.title.toUpperCase()+'\n';QUESTIONS.filter(q=>q.section===s.id).forEach(q=>{const a=state.answers[q.id];text+=`Q${q.id}. ${q.prompt}\nMy answer: ${answered(q,state.answers)?q.type==='mc'?String.fromCharCode(65+a)+'. '+q.options[a]:a:'[not answered]'}\n`;if(state.checked){if(q.type==='mc')text+=`Correct answer: ${String.fromCharCode(65+q.answer)}. ${q.options[q.answer]}\n`;else text+=`Model: ${q.model}\nChecks: ${q.checks.join(' ')}\nSelf-check: ${({0:'Needs revision',1:'Meets one check',2:'Meets both checks'})[state.ratings[q.id]]??'Not compared yet'}\n`;text+=q.explanation+'\n';}text+='\n';});if(state.checked){const r=resultsFor(s.id,state.answers,state.ratings);text+=`Topic evidence: ${r.correct}/${r.total} choices correct; short response ${r.reviewed?'self-rated '+r.shortPoints+'/2 checks met':'not compared yet'}.\n\n`;}});const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Unit-1-Sound-Check-Answers.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('saveCopy').addEventListener('click',saveAnswerCopy);$('profile').addEventListener('click',e=>{if(e.target.id==='downloadResults')saveAnswerCopy();if(e.target.id==='printResults')printReview(true);});
function printReview(withAnswers){$('printArea').innerHTML=`<h1>Unit 1 · Sound Check</h1><p><strong>Discover Futures 4 · Prep IS English · 15–20 minutes</strong></p>${withAnswers?'':'<p>Name: __________________________ Class: __________ Date: __________</p>'}<p>Choose one answer for each multiple-choice question. Write one brief sentence for each short response.</p>`+SECTIONS.map(s=>`<h2>${s.title}</h2>${QUESTIONS.filter(q=>q.section===s.id).map(q=>`<div class="print-q"><h3>${q.id}. ${escapeHtml(q.prompt)}</h3>${q.type==='mc'?`<ol type="A">${q.options.map(o=>`<li>${escapeHtml(o)}</li>`).join('')}</ol>`:withAnswers?'':'<div class="line"></div>'}${withAnswers?`<p><strong>My answer:</strong> ${escapeHtml(q.type==='mc'?String.fromCharCode(65+state.answers[q.id])+'. '+q.options[state.answers[q.id]]:state.answers[q.id])}</p>${q.type==='mc'?`<p><strong>Correct:</strong> ${String.fromCharCode(65+q.answer)}. ${escapeHtml(q.options[q.answer])}</p>`:`<p><strong>Model:</strong> ${escapeHtml(q.model)}</p><p><strong>Checks:</strong> ${escapeHtml(q.checks.join(' '))}</p><p><strong>My comparison:</strong> ${({0:'Needs revision',1:'Meets one check',2:'Meets both checks'})[state.ratings[q.id]]??'Not compared yet'}</p>`}<p>${escapeHtml(q.explanation)}</p>`:''}</div>`).join('')}`).join('')+(withAnswers?`<div class="print-profile"><h2>My topic evidence</h2>${SECTIONS.map(s=>{const r=resultsFor(s.id,state.answers,state.ratings);return `<p><strong>${s.title}:</strong> ${r.correct}/${r.total} choices correct. Short response: ${r.reviewed?'self-rated '+r.shortPoints+'/2 checks met':'not compared yet'}.</p>`;}).join('')}<p>Multiple-choice results are automatic. Short responses are self-compared. This is a sample of understanding, not a final ability judgement.</p></div>`:'');window.print();}
$('printBlank').addEventListener('click',()=>printReview(false));
$('restart').addEventListener('click',()=>{if(!confirm('Start a new attempt? This removes this browser’s current answers and self-checks. Save an answer copy first if you want to keep them.'))return;pauseTimer();state={answers:{},ratings:{},section:0,checked:false,remaining:1080};$('timerNote').textContent='A guide, not a deadline. Nothing locks when time runs out.';$('timerBtn').textContent='Start';persist();timerDisplay();renderSection();renderProfile();$('status').textContent='New attempt ready.';window.scrollTo({top:0,behavior:'smooth'});});
renderSection();renderProfile();timerDisplay();if(!storageWorks)$('saveState').textContent='This browser cannot save automatically. Use “Save answer copy” before leaving.';
